function canvasOption(o,section){const oi=mediaDisplay(o.image||''),img=oi?'<div class="qs-option-image" style="background-image:url(&quot;'+esc(oi)+'&quot;)"></div>':'<div class="qs-option-image empty"><span>ADD IMAGE</span></div>';return '<article class="qs-client-option '+(o.selected?'selected':'')+'" data-qs-option-card="'+esc(o.id)+'">'+img+'<div class="qs-option-content">'+(o.recommended||o.badge?'<span class="badge">'+esc(o.recommended?'Pool Bros Recommended':o.badge)+'</span>':'')+'<h4>'+esc(o.title)+'</h4><p>'+esc(o.description||o.subtitle||'Configured for this project.')+'</p><strong>'+((section.priceMode==='included')?'Included':cash(Number(o.qty||1)*Number(o.unitPrice||0)))+'</strong><button type="button" data-qs-select-option="'+esc(o.id)+'">'+(o.selected?'Selected':'Select')+'</button></div></article>'}
function optionsView(qt){if(!selectedSectionId&&qt.sections[0])selectedSectionId=qt.sections[0].id;const s=selectedSection();if(s&&!selectedOptionId&&s.options[0]&&!selectedBlockId)selectedOptionId=s.options[0].id;const o=selectedOption(),b=selectedBlock(),options=s?(s.options||[]):[],media=mediaList(qt);const sectionList=(qt.sections||[]).map((x,i)=>'<div class="qs-section-row '+(x.id===s?.id?'active':'')+'" data-qs-section="'+esc(x.id)+'"><i>'+String(i+1).padStart(2,'0')+'</i><div><b>'+esc(x.title)+'</b><small>'+esc(x.rule)+' · '+(x.options||[]).length+' options</small></div>'+badge(x.visible===false?'Hidden':'Live')+'</div>').join('');const products=(data().products||[]).filter(p=>!p.deleted&&(!productSearch||[p.name,p.sku,p.category,p.supplier].join(' ').toLowerCase().includes(productSearch.toLowerCase()))).slice(0,40);let panel='';if(builderPanel==='sections')panel='<div class="qs-card-head compact"><div><h3>Proposal sections</h3><p>Each section is a customer decision or specification group.</p></div></div><div class="qs-section-list">'+sectionList+'</div><div class="qs-toolbar" style="margin-top:8px">'+button('+ Section','add-section')+(s?button('Duplicate','duplicate-section'):'')+(qt.sections.length>1?button('Delete','delete-section','danger'):'')+'</div><div class="qs-quick-section"><span>QUICK SECTION</span><button data-qs-section-template="single">Single choice</button><button data-qs-section-template="optional">Optional upgrades</button><button data-qs-section-template="locked">Included specification</button></div>';else if(builderPanel==='elements')panel='<div class="qs-card-head compact"><div><h3>Content blocks</h3><p>Click once to add it to the live proposal.</p></div></div><div class="qs-element-grid">'+[['heading','Heading'],['text','Text'],['callout','Callout'],['image','Image'],['gallery','Gallery'],['brochure','Brochure'],['poollayout','Pool layout'],['testimonial','Testimonial'],['payment','Payments'],['note','Design note']].map(x=>'<button type="button" data-qs-add-block="'+x[0]+'"><span class="qs-element-icon">'+x[1].slice(0,2).toUpperCase()+'</span>'+esc(x[1])+'<small>Proposal layer</small></button>').join('')+'</div>';else if(builderPanel==='media')panel='<div class="qs-card-head compact"><div><h3>Media library</h3><p>Upload once, then reuse it across this quote.</p></div></div><button type="button" class="qs-upload-zone" data-qs-upload-target="library"><b>＋ Upload project image</b><span>Drop JPG, PNG or WebP here, or click to browse. Images are resized automatically.</span></button><div class="qs-media-meter"><span>Quote media</span><b>'+Math.round(mediaSize(qt)/1024)+' KB</b></div><div class="qs-media-grid">'+(media.length?media.map(m=>'<div class="qs-media-item">'+mediaThumb(m)+'<div class="qs-media-actions"><button data-qs-use-media="'+esc(m.id)+'">Use</button><button data-qs-remove-media="'+esc(m.id)+'">×</button></div></div>').join(''):'<div class="qs-empty qs-empty-small"><p>No images uploaded yet.</p></div>')+'</div>';else panel='<div class="qs-card-head compact"><div><h3>Product Hub</h3><p>SKU, supplier and cost remain linked underneath.</p></div></div><input data-qs-product-search placeholder="Search Product Hub" value="'+esc(productSearch)+'" class="qs-side-search"><div class="qs-product-picker elite">'+products.map(p=>'<div class="qs-product-pick"><div class="qs-product-pick-image" '+(p.image||p.imageUrl?'style="background-image:url(&quot;'+esc(p.image||p.imageUrl)+'&quot;)"':'')+'></div><div><b>'+esc(p.name||p.sku)+'</b><small>'+esc(p.sku||p.id)+' · '+esc(p.supplier||'')+'</small><strong>'+cash(p.rrp||p.sellPrice||p.price||0)+'</strong></div><button class="qs-btn" data-qs-add-product="'+esc(p.id)+'">Add</button></div>').join('')+'</div>';
 const left='<aside class="qs-builder-side left elite"><div class="qs-builder-nav"><button class="'+(builderPanel==='sections'?'active':'')+'" data-qs-builder-panel="sections">Sections</button><button class="'+(builderPanel==='elements'?'active':'')+'" data-qs-builder-panel="elements">Elements</button><button class="'+(builderPanel==='media'?'active':'')+'" data-qs-builder-panel="media">Media</button><button class="'+(builderPanel==='products'?'active':'')+'" data-qs-builder-panel="products">Products</button></div><div class="qs-builder-panel">'+panel+'</div></aside>';
 const blocks=(s?.blocks||[]).map(blockPreview).join('');const center='<main class="qs-canvas-stage elite"><div class="qs-canvas-toolbar"><span>CLIENT CANVAS</span><div>'+button('Add content','builder-elements')+button('Preview','preview')+'</div></div><div class="qs-canvas"><header class="qs-canvas-head"><div><b>POOL BROS</b><small>Private client proposal</small></div><span>'+esc(qt.id)+'</span></header><div class="qs-canvas-body">'+(s?'<span class="eyebrow">'+esc(String(s.eyebrow||'YOUR CHOICES').toUpperCase())+'</span><h3>'+esc(s.title)+'</h3><p>'+esc(s.intro||'')+'</p>'+blocks+'<div class="qs-client-options layout-'+esc(s.layout||'cards')+'" style="grid-template-columns:repeat('+Math.max(1,Number(s.style?.columns||3))+',minmax(0,1fr));gap:'+Number(s.style?.spacing||18)+'px">'+options.filter(x=>x.visible!==false).map(x=>canvasOption(x,s)).join('')+'</div>':'<div class="qs-empty"><h3>Add a section</h3></div>')+'</div></div></main>';
 let inspectorContent='';if(b)inspectorContent=blockInspector(b);else if(o)inspectorContent=optionInspector(o);else if(s)inspectorContent='<div class="qs-inspector-head"><div><span class="qs-layer-kicker">SECTION DESIGN</span><h3>'+esc(s.title)+'</h3></div></div>'+sectionDesignForm(s);const optionLayers=s?'<div class="qs-layer-stack"><div class="qs-layer-title">OPTIONS</div>'+options.map(x=>'<button type="button" class="qs-layer-row '+(x.id===o?.id&&!b?'active':'')+'" data-qs-option="'+esc(x.id)+'"><span class="qs-layer-thumb" '+(mediaDisplay(x.image||'')?'style="background-image:url(&quot;'+esc(mediaDisplay(x.image||''))+'&quot;)"':'')+'></span><span><b>'+esc(x.title)+'</b><small>'+cash(Number(x.qty||1)*Number(x.unitPrice||0))+'</small></span></button>').join('')+'<button type="button" class="qs-layer-add" data-qs-action="add-custom">＋ Bespoke option</button></div>':'';const inspector='<aside class="qs-builder-side right elite">'+inspectorContent+optionLayers+'</aside>';
 return '<div class="qs-builder elite">'+left+center+inspector+'</div><input id="qsImageUpload" type="file" accept="image/jpeg,image/png,image/webp" hidden>'}
function blockPreview(b){const cls='qs-editable-block '+(b.id===selectedBlockId?'selected':'');const wrap=(content)=>'<div class="'+cls+'" data-qs-block="'+esc(b.id)+'"><div class="qs-block-handle">'+esc(b.type)+'</div>'+content+'</div>';if(b.type==='heading')return wrap('<h4 style="font-family:Georgia,serif;font-size:'+(b.style?.size||24)+'px;text-align:'+esc(b.style?.align||'left')+'">'+esc(b.text||b.title||'Heading')+'</h4>');if(b.type==='text')return wrap('<p class="qs-block-copy" style="text-align:'+esc(b.style?.align||'left')+'">'+esc(b.text||'Add supporting copy.')+'</p>');if(b.type==='callout')return wrap('<div class="qs-notice" style="text-align:'+esc(b.style?.align||'left')+'">'+esc(b.text||'Project recommendation')+'</div>');if(b.type==='image'){const u=mediaDisplay(b.url||'');return wrap(u?'<div class="qs-builder-image" style="background-image:url(&quot;'+esc(u)+'&quot;)"></div>':'<div class="qs-builder-image empty"><span>Click this layer, then upload an image</span></div>')}if(b.type==='gallery'){const imgs=(b.images||[]).slice(0,4).map(u=>mediaDisplay(u)).filter(Boolean);return wrap('<div class="qs-builder-gallery">'+(imgs.length?imgs.map(u=>'<i style="background-image:url(&quot;'+esc(u)+'&quot;)"></i>').join(''):'<i class="empty"></i><i class="empty"></i><i class="empty"></i>')+'</div>')}if(b.type==='testimonial')return wrap('<blockquote>“'+esc(b.text||'A beautifully delivered project from start to finish.')+'”</blockquote>');if(b.type==='brochure')return wrap('<div class="qs-notice"><b>'+esc(b.title||'Supporting brochure')+'</b><br>'+esc(b.text||'Controlled project document')+'</div>');if(b.type==='payment')return wrap('<div class="qs-notice"><b>Payment milestones</b><br>Shown automatically from the quote payment schedule.</div>');if(b.type==='poollayout')return wrap('<div class="qs-notice"><b>Bespoke pool layout</b><br>Linked from Pool Layout Studio.</div>');if(b.type==='note')return wrap('<div class="qs-note-preview">'+esc(b.text||'Project-specific design note.')+'</div>');return wrap('')}
function optionInspector(o){if(!o)return '<div class="qs-empty qs-empty-small"><h3>Select an option</h3><p>Click an option card or add a Product Hub item to edit it.</p></div>';const oi=mediaDisplay(o.image||''),img=oi?'<div class="qs-inspector-image" style="background-image:url(&quot;'+esc(oi)+'&quot;)"></div>':'<div class="qs-inspector-image empty"><span>No image yet</span></div>';return '<div class="qs-inspector-head"><div><span class="qs-layer-kicker">SELECTED OPTION</span><h3>'+esc(o.title)+'</h3></div></div>'+img+'<div class="qs-toolbar" style="margin:8px 0 12px"><button type="button" class="qs-btn accent" data-qs-upload-target="option">'+(o.image?'Replace image':'Upload image')+'</button>'+(o.image?button('Remove image','remove-option-image','danger'):'')+'</div><form id="qsOptionForm" class="qs-fields" style="grid-template-columns:1fr"><input type="hidden" name="optionId" value="'+esc(o.id)+'">'+field('Customer title','title',o.title)+field('Subtitle','subtitle',o.subtitle||'')+textarea('Description','description',o.description||'')+field('Benefits','benefits',(o.benefits||[]).join(', '))+field('Quantity','qty',o.qty||1,'number','min="0.01" step="0.01"')+field('Customer price ex VAT','unitPrice',o.unitPrice||0,'number','min="0" step="0.01"')+field('Badge','badge',o.badge||'')+'<label class="qs-check"><input name="selected" type="checkbox" '+(o.selected?'checked':'')+'> Selected / pre-selected</label><label class="qs-check"><input name="recommended" type="checkbox" '+(o.recommended?'checked':'')+'> Pool Bros recommended</label><label class="qs-check"><input name="visible" type="checkbox" '+(o.visible!==false?'checked':'')+'> Visible to customer</label><button class="qs-btn primary" type="submit">Save option</button>'+button('Remove option','remove-option','danger')+'</form>'}
function svgShape(layout){const shape=layout.shape||'rectangle';let body='<rect x="130" y="90" width="540" height="290" rx="'+(shape==='oval'?145:shape==='roman'?55:shape==='kidney'?80:10)+'" fill="#d8edf0" stroke="#355c66" stroke-width="4"/>';
 if(shape==='kidney')body='<path d="M185 115 C320 45 395 145 500 100 C625 45 720 130 675 260 C630 390 510 330 410 365 C280 410 130 335 150 220 C160 165 170 135 185 115Z" fill="#d8edf0" stroke="#355c66" stroke-width="4"/>';
 if(shape==='lshape')body='<path d="M140 90 H650 V235 H475 V385 H140 Z" fill="#d8edf0" stroke="#355c66" stroke-width="4"/>';
 if(shape==='custom'&&layout.customPoints?.length>=3)body='<polygon points="'+layout.customPoints.map(p=>(p.x||0)+','+(p.y||0)).join(' ')+'" fill="#d8edf0" stroke="#355c66" stroke-width="4"/>';
 if(shape==='hopper')body+='<path d="M330 185 L545 185 L605 320 L265 320 Z" fill="none" stroke="#537b84" stroke-width="3" stroke-dasharray="10 8"/><line x1="330" y1="90" x2="330" y2="380" stroke="#73949b" stroke-dasharray="8 7"/><text x="190" y="235" font-size="15" fill="#43616a">Shallow floor</text><text x="390" y="250" font-size="15" fill="#43616a">Deep hopper</text>';
 return body}
function componentIcon(c,selected){const x=Number(c.x||400),y=Number(c.y||235),label={skimmer:'SK',return:'R',light:'L',steps:'ST',cover:'CP',drain:'D',topup:'TU',jet:'J'}[c.type]||'•';return '<g data-qs-layout-item="'+esc(c.id)+'" style="cursor:pointer"><circle cx="'+x+'" cy="'+y+'" r="18" fill="'+(selected?'#9d5149':'#172920')+'" stroke="#fff" stroke-width="3"/><text x="'+x+'" y="'+(y+4)+'" text-anchor="middle" font-size="10" font-weight="700" fill="#fff">'+label+'</text></g>'}
function layoutView(qt){const l=qt.poolLayout||{},components=l.components||[];const shapes=[['rectangle','Rectangle'],['hopper','Hopper'],['roman','Roman End'],['oval','Oval'],['kidney','Kidney'],['lshape','L-Shape'],['custom','Custom']];return '<div class="qs-layout-workspace"><aside class="qs-layout-tools"><h3 style="font-size:13px">Pool shape</h3><div class="qs-shape-grid">'+shapes.map(x=>'<button type="button" class="'+(l.shape===x[0]?'active':'')+'" data-qs-shape="'+x[0]+'">'+x[1]+'</button>').join('')+'</div><hr style="border:0;border-top:1px solid var(--qs-line);margin:13px 0"><h3 style="font-size:13px">Components</h3><div class="qs-component-grid">'+[['skimmer','Skimmer'],['return','Return'],['topup','Auto top-up'],['jet','Jet'],['light','Light'],['steps','Steps'],['cover','Cover pit'],['drain','Main drain']].map(x=>'<button type="button" data-qs-component="'+x[0]+'">+ '+x[1]+'</button>').join('')+'</div><div class="qs-help" style="margin-top:10px">Add a component then click it on the drawing to select/remove it. Exact dimensions and positions are stored with the quote version.</div></aside><main class="qs-layout-canvas"><div class="qs-toolbar" style="justify-content:space-between;margin-bottom:9px"><div><b>Client pool layout</b><div class="qs-help">'+esc(String(l.shape||'rectangle').toUpperCase())+' · '+esc(l.length||10)+'m × '+esc(l.width||4)+'m</div></div>'+button('Clear components','clear-layout','danger')+'</div><svg class="qs-pool-svg" viewBox="0 0 800 470">'+svgShape(l)+(components||[]).map(c=>componentIcon(c,c.id===layoutSelected)).join('')+'<text x="400" y="430" text-anchor="middle" font-size="14" fill="#607077">'+esc(l.length||10)+'m overall length · '+esc(l.width||4)+'m width</text></svg></main><aside class="qs-layout-inspector"><h3 style="font-size:13px">Dimensions & profile</h3><form id="qsLayoutForm" class="qs-fields" style="grid-template-columns:1fr">'+field('Length (m)','length',l.length||10,'number','min="1" step="0.1"')+field('Width (m)','width',l.width||4,'number','min="1" step="0.1"')+field('Shallow depth (m)','shallowDepth',l.shallowDepth||1.1,'number','min="0.5" step="0.05"')+field('Deep depth (m)','deepDepth',l.deepDepth||1.8,'number','min="0.5" step="0.05"')+(l.shape==='hopper'?field('Shallow floor length (m)','shallowLength',l.shallowLength||3,'number','step="0.1"')+field('Slope length (m)','slopeLength',l.slopeLength||3,'number','step="0.1"'):'')+textarea('Layout notes','notes',l.notes||'')+'<button class="qs-btn primary" type="submit">Save pool layout</button></form><hr style="border:0;border-top:1px solid var(--qs-line);margin:13px 0"><div class="qs-selected-item">'+(layoutSelected?'Selected: '+esc((components.find(c=>c.id===layoutSelected)||{}).type||'component'):'Select a placed component')+'</div>'+button('Remove selected','remove-layout-item','danger',layoutSelected?'':'disabled')+'<div class="qs-mini-list" style="margin-top:10px">'+components.map(c=>'<div class="qs-mini-row"><span>'+esc(c.type)+'</span><button class="qs-link" data-qs-layout-select="'+esc(c.id)+'">Select</button></div>').join('')+'</div></aside></div>'}
function commercialView(qt){const t=engine.totals(qt),ap=engine.approvalState(qt),selected=engine.selectedOptions(qt),pay=engine.paymentSummary(qt),hp=engine.normalisePolicy(qt);const rows=selected.map(({section,option:o})=>'<tr><td><strong>'+esc(o.title)+'</strong><small>'+esc(section.title)+' · '+esc(o.skuSnapshot||o.kind)+'</small></td><td>'+esc(o.qty||1)+'</td><td>'+cash(o.unitPrice)+'</td><td>'+cash(o.costSnapshot)+'</td><td>'+cash(Number(o.qty||1)*Number(o.unitPrice||0))+'</td></tr>').join('');let payment;if(pay.mode==='full')payment='<div class="qs-mini-list"><div class="qs-mini-row"><span>100% · Accepted quote payment</span><strong>'+cash(t.gross)+'</strong></div></div>';else if(pay.mode==='deposit')payment=qt.workflow==='quick'?'<div class="qs-mini-list"><div class="qs-mini-row"><span>'+esc(qt.depositPercent)+'% · Deposit</span><strong>'+cash(t.deposit)+'</strong></div><div class="qs-mini-row"><span>'+Math.max(0,100-Number(qt.depositPercent))+'% · Balance</span><strong>'+cash(t.gross-t.deposit)+'</strong></div></div>':'<div class="qs-mini-list"><div class="qs-mini-row"><span>'+esc(qt.depositPercent)+'% · Secure project</span><strong>'+cash(t.deposit)+'</strong></div><div class="qs-mini-row"><span>40% · Installation milestone</span><strong>'+cash(t.gross*.4)+'</strong></div><div class="qs-mini-row"><span>'+Math.max(0,100-Number(qt.depositPercent)-40)+'% · Completion</span><strong>'+cash(t.gross*Math.max(0,100-Number(qt.depositPercent)-40)/100)+'</strong></div></div>';else payment='<div class="qs-notice"><b>No automatic Xero request</b><br>Acceptance still creates the operational records. Finance can invoice manually.</div>';return '<div class="qs-metric-grid"><div class="qs-metric"><small>NET SELL</small><strong>'+cash(t.net)+'</strong></div><div class="qs-metric"><small>VAT</small><strong>'+cash(t.vat)+'</strong></div><div class="qs-metric"><small>'+(qt.workflow==='quick'?'QUOTE TOTAL':'PROJECT INVESTMENT')+'</small><strong>'+cash(t.gross)+'</strong></div><div class="qs-metric"><small>FORECAST MARGIN</small><strong>'+t.margin.toFixed(1)+'%</strong></div></div><div style="height:12px"></div><div class="qs-grid-2">'+card('Commercial Control','Internal only. None of this cost or margin data is included in the customer payload.','<div class="qs-notice '+(ap.required?'warn':'')+'"><b>'+(ap.required?'Approval required':'Commercial controls pass')+'</b><br>'+(ap.required?esc(ap.problems.map(x=>x.label).join(' · ')||'Pending approval'):'Quote is within current minimum margin guardrails.')+'</div><div class="qs-toolbar" style="margin-top:10px">'+(ap.required?button('Approve exception','approve-exception','bronze'):'')+'</div>')+card('Acceptance Handover',workflowLabel(qt)+' · '+(hp.createProjectOnAcceptance?'Project + Sales Order':'Sales Order only')+'.',payment)+'</div><div style="height:12px"></div>'+card('Accepted SKU / Cost Snapshot','Selected options are frozen into the published version. Product Hub can change later without changing what the customer accepted.','<div class="qs-table-wrap"><table class="qs-table"><thead><tr><th>Quote item</th><th>Qty</th><th>Sell ex VAT</th><th>Cost snapshot</th><th>Line total</th></tr></thead><tbody>'+rows+'</tbody></table></div>')}
function engagementView(qt){const e=qt.engagement||{},score=engine.engagementScore(qt),events=e.events||[],seen=Object.values(e.sections||{}).filter(x=>x?.seen).length;return '<div class="qs-metric-grid"><div class="qs-metric"><small>ENGAGEMENT</small><strong>'+esc(score.label)+'</strong></div><div class="qs-metric"><small>VISITS</small><strong>'+Number(e.visits||0)+'</strong></div><div class="qs-metric"><small>ENGAGED TIME</small><strong>'+Math.round(Number(e.engagedSeconds||0)/60)+'m</strong></div><div class="qs-metric"><small>SECTIONS SEEN</small><strong>'+seen+'</strong></div></div><div style="height:12px"></div>'+card('Customer Activity Timeline','Accurate activity signals: opened, seen and interacted. Pool Shed never labels a page “read” merely because it loaded.','<div class="qs-timeline">'+(events.length?events.map(ev=>'<div class="qs-event"><time>'+esc(new Date(ev.time||ev.at||Date.now()).toLocaleString('en-GB',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}))+'</time><i>•</i><div><b>'+esc(ev.title||ev.type||'Activity')+'</b><span>'+esc(ev.detail||'')+'</span></div>'+badge(ev.category||'activity')+'</div>').join(''):'<div class="qs-empty"><i>◉</i><h3>No customer activity yet</h3><p>Once a secure customer link is published, proposal opens and meaningful interactions appear here.</p></div>')+'</div>')}
function versionsView(qt){const rows=(qt.versions||[]).slice().reverse().map(v=>'<div class="qs-version"><strong>V'+v.number+'</strong><div><b>'+esc(v.status)+'</b><small>'+esc(new Date(v.createdAt).toLocaleString('en-GB'))+' · Hash '+esc(String(v.hash||'').slice(0,12))+'</small></div>'+badge(v.number===qt.publishedVersion?'Current':'Frozen',v.number===qt.publishedVersion?'good':'')+'<span>'+cash(v.publicSnapshot?.investment?.gross||v.commercialSnapshot?.totals?.gross||0)+'</span></div>').join('');return '<div class="qs-grid-2">'+card('Immutable Version History','A published customer version is never edited. Changes require a new draft/revision.','<div>'+ (rows||'<div class="qs-empty"><i>V</i><h3>No published version yet</h3><p>Use Publish & Send when the proposal passes pre-flight checks.</p></div>')+'</div>',button('Create revision','create-revision'))+card('Delivery History','Secure publication links and recipients.','<div class="qs-mini-list">'+((qt.deliveries||[]).slice().reverse().map(d=>'<div class="qs-mini-row"><span><b>V'+d.version+' · '+esc(d.recipientEmail||'Preview')+'</b><br><small>'+esc(d.status)+' · '+esc(new Date(d.at).toLocaleString('en-GB'))+'</small></span><span>'+esc(d.expiresAt||'')+'</span></div>').join('')||'<span class="qs-help">No delivery record yet.</span>')+'</div>')+'</div>'}
function handoverView(qt){const c=qt.conversion,t=engine.totals(qt),hp=engine.normalisePolicy(qt),pay=engine.paymentSummary(qt);if(!c)return '<div class="qs-empty"><i>⇢</i><h3>Operational handover waits for acceptance</h3><p>'+(qt.workflow==='quick'?'This Quick Quote will create a Sales Order immediately on acceptance'+(hp.createProjectOnAcceptance?' and a linked Project.':'. No Project will be created.'):'This Project Proposal will create the Project, Sales Order, stock demand and supplier PO drafts.')+' The customer never sees this workspace.</p>'+(qt.status==='Accepted'?button('Create handover','convert-accepted','primary'):'')+'</div>';const d=data(),job=c.projectId?(d.jobs||[]).find(x=>x.id===c.projectId):null,so=(d.salesOrders||[]).find(x=>x.id===c.salesOrderId),pos=(d.purchaseOrders||[]).filter(x=>(c.purchaseOrderIds||[]).includes(x.id)),dep=c.deposit||{},paymentRequired=dep.mode!=='none'&&dep.status!=='Not required',paymentDone=!paymentRequired||dep.status==='Paid';const flow=[['Accepted version','V'+qt.publishedVersion,true],...(hp.createProjectOnAcceptance?[['Project',c.projectId,!!job]]:[]),['Sales Order',c.salesOrderId,!!so],['Stock & POs',pos.length+' PO drafts',!!so],[(dep.label||pay.label),dep.status,paymentDone]];const projectCard='<div class="qs-handover-card"><small>PROJECT</small><strong>'+(c.projectId?esc(c.projectId):'Not required')+'</strong>'+(c.projectId?button('Open Projects','open-project'):'<span class="qs-help">Quick Quote · Sales Order only</span>')+'</div>';const payButton=dep.status==='Ready to queue'?button('Queue Xero '+(dep.mode==='full'?'invoice':'deposit'),'queue-deposit','accent'):dep.status==='Queued to Xero'?button('Record payment received','mark-paid','bronze'):((dep.status==='Paid'||dep.status==='Not required')?button('Release POs','release-pos','primary'):'');return '<div class="qs-flow '+(flow.length===4?'quick':'')+'">'+flow.map(x=>'<div class="qs-flow-step '+(x[2]?'done':'')+'"><b>'+esc(x[0])+'</b><span>'+esc(x[1]||'Waiting')+'</span></div>').join('')+'</div><div style="height:12px"></div><div class="qs-handover-links">'+projectCard+'<div class="qs-handover-card"><small>SALES ORDER</small><strong>'+esc(c.salesOrderId||'Waiting')+'</strong>'+button('Open Sales Orders','open-so')+'</div><div class="qs-handover-card"><small>PROCUREMENT</small><strong>'+pos.length+' draft POs</strong>'+button('Open Purchasing','open-purchase')+'</div><div class="qs-handover-card"><small>XERO '+esc(String(dep.label||pay.label).toUpperCase())+'</small><strong>'+cash(dep.amount||pay.amount||0)+'</strong><span class="qs-help">'+esc(dep.status||'Ready')+'</span></div></div><div style="height:12px"></div><div class="qs-grid-2">'+card('Payment & Procurement Gate',hp.requirePaymentBeforePORelease&&dep.mode!=='none'?'Supplier PO drafts are prepared at acceptance and held until payment is confirmed.':'Supplier PO drafts still require purchasing review, but payment is not a release gate.','<div class="qs-notice '+(paymentDone?'':'warn')+'"><b>'+esc(dep.status||'Ready')+'</b><br>'+(dep.financeDocumentId?'Finance document '+esc(dep.financeDocumentId):dep.mode==='none'?'No automatic Xero request is configured.':'Link the customer to Xero if required, then queue the payment request.')+'</div><div class="qs-toolbar" style="margin-top:10px">'+payButton+'</div>')+card('Handover Trace','The accepted quote/version remains the source reference for every operational line.','<div class="qs-mini-list"><div class="qs-mini-row"><span>Workflow</span><b>'+esc(workflowLabel(qt))+'</b></div><div class="qs-mini-row"><span>Quote</span><b>'+esc(qt.id)+' v'+qt.publishedVersion+'</b></div><div class="qs-mini-row"><span>Project</span><b>'+esc(c.projectId||'Not created')+'</b></div><div class="qs-mini-row"><span>Sales Order</span><b>'+esc(c.salesOrderId||'')+'</b></div><div class="qs-mini-row"><span>Supplier POs</span><b>'+esc((c.purchaseOrderIds||[]).join(', ')||'None required')+'</b></div></div>')+'</div>'}
function detailView(qt){let body;if(detailTab==='Proposal')body=proposalView(qt);else if(detailTab==='Options & Packages')body=optionsView(qt);else if(detailTab==='Pool Layout')body=layoutView(qt);else if(detailTab==='Commercial')body=commercialView(qt);else if(detailTab==='Engagement')body=engagementView(qt);else if(detailTab==='Versions')body=versionsView(qt);else body=handoverView(qt);return '<div class="qs-root">'+quoteHead(qt)+quoteTabs(qt)+'<main class="qs-detail-body">'+body+'</main>'+sendDialog(qt)+'</div>'}
function templatesView(){const t=engine.templates();return '<div class="qs-root"><section class="qs-command"><div><span class="kicker">REUSABLE PROPOSAL SYSTEM</span><h2>Quote Templates</h2><p>Templates can carry presentation pages, option groups, layout defaults and standard client wording while keeping current Product Hub SKUs/prices under staff control.</p></div><div class="qs-command-actions">'+button('Back to quotes','back-list')+'</div></section>'+card('Templates','Save an approved quote structure as a reusable starting point.','<div class="qs-section-list">'+(t.map(x=>'<div class="qs-section-row"><i>T</i><div><b>'+esc(x.name)+'</b><small>'+esc(x.projectType||'Proposal')+' · '+esc(new Date(x.createdAt).toLocaleDateString('en-GB'))+'</small></div><span></span></div>').join('')||'<div class="qs-empty"><i>T</i><h3>No templates yet</h3><p>Open an approved quote and save it as a template from Versions.</p></div>')+'</div>')+'</div>'}
function globalEngagementView(){const qs=engine.listQuotes().filter(x=>(x.engagement?.visits||0)>0);return '<div class="qs-root"><section class="qs-command"><div><span class="kicker">CUSTOMER INTENT</span><h2>Quote Engagement</h2><p>See the proposals clients are actively considering without pretending a page load proves they have read every word.</p></div></section>'+card('Active proposals','Prioritised by meaningful engagement.','<div class="qs-table-wrap"><table class="qs-table"><thead><tr><th>Quote</th><th>Customer</th><th>Signal</th><th>Visits</th><th>Last activity</th><th></th></tr></thead><tbody>'+qs.sort((a,b)=>engine.engagementScore(b).score-engine.engagementScore(a).score).map(x=>'<tr><td><b>'+esc(x.id)+'</b><small>'+esc(x.projectName)+'</small></td><td>'+esc(customerName(x))+'</td><td>'+badge(engine.engagementScore(x).label,engine.engagementScore(x).score>=70?'good':'blue')+'</td><td>'+Number(x.engagement?.visits||0)+'</td><td>'+esc(lastActivity(x))+'</td><td>'+button('Open','open-quote','','data-quote-id="'+esc(x.id)+'"')+'</td></tr>').join('')+'</tbody></table></div>')+'</div>'}
function approvalsView(){const qs=engine.listQuotes().filter(x=>engine.approvalState(x).required);return '<div class="qs-root"><section class="qs-command"><div><span class="kicker">COMMERCIAL CONTROL</span><h2>Quote Approvals</h2><p>Only genuine exceptions enter the approval queue. Healthy quotes do not create pointless pending records.</p></div></section>'+card('Approval Queue','Margin, discount and override controls stay internal.','<div class="qs-table-wrap"><table class="qs-table"><thead><tr><th>Quote</th><th>Customer</th><th>Exception</th><th>Value</th><th></th></tr></thead><tbody>'+ (qs.map(x=>{const a=engine.approvalState(x),t=engine.totals(x);return '<tr><td><b>'+esc(x.id)+'</b><small>'+esc(x.projectName)+'</small></td><td>'+esc(customerName(x))+'</td><td>'+esc(a.problems.map(p=>p.label).join(' · ')||'Pending commercial approval')+'</td><td>'+cash(t.gross)+'</td><td>'+button('Review','open-quote','','data-quote-id="'+esc(x.id)+'"')+'</td></tr>'}).join('')||'<tr><td colspan="5"><div class="qs-empty"><i>✓</i><h3>No quote approvals waiting</h3><p>Commercial controls currently pass.</p></div></td></tr>')+'</tbody></table></div>')+'</div>'}
function settingsView(){const s=engine.settings();return '<div class="qs-root"><section class="qs-command"><div><span class="kicker">QUOTE EXPERIENCE</span><h2>Quote Studio Settings</h2><p>Customer presentation settings are separated from internal Pool Shed colours and operational controls.</p></div></section>'+card('Defaults','Applied to new quotes; existing published versions never change.','<form id="qsSettingsForm" class="qs-fields">'+field('Client brand name','brandName',s.brandName)+field('Client descriptor','brandDescriptor',s.brandDescriptor)+field('Default terms version','termsVersion',s.termsVersion)+field('Default validity days','validDays',s.validDays,'number','min="1"')+field('Default deposit %','depositPercent',s.depositPercent,'number','min="0" max="100"')+field('Minimum margin %','minimumMargin',s.minimumMargin,'number','min="0" max="100"')+field('Proposal primary colour','primary',s.primary,'color')+field('Proposal accent colour','accent',s.accent,'color')+'<div class="qs-field full"><button class="qs-btn primary" type="submit">Save Quote Studio defaults</button></div></form>')+'</div>'}
function sendDialog(qt){if(!sendModal)return '';const check=engine.validate(qt),t=engine.totals(qt),pay=engine.paymentSummary(qt);const c=engine.customer(qt.customerId)||{};return '<div class="qs-modal-backdrop show"><div class="qs-modal"><header class="qs-modal-head"><div><b>Publish & Send</b><div class="qs-help">Freeze the exact customer experience and handover workflow before creating the secure link.</div></div>'+button('Close','close-send')+'</header><div class="qs-modal-body"><div class="qs-metric-grid"><div class="qs-metric"><small>'+(qt.workflow==='quick'?'QUOTE':'PROJECT')+'</small><strong>'+cash(t.gross)+'</strong></div><div class="qs-metric"><small>'+esc(String(pay.label).toUpperCase())+'</small><strong>'+cash(pay.amount)+'</strong></div><div class="qs-metric"><small>VERSION</small><strong>V'+(Number(qt.currentVersion||0)+1)+'</strong></div><div class="qs-metric"><small>WORKFLOW</small><strong style="font-size:16px">'+esc(workflowLabel(qt))+'</strong></div></div><div style="height:12px"></div><div class="qs-notice"><b>'+esc(workflowLabel(qt))+'</b><br>'+(qt.workflow==='quick'?'On acceptance Pool Shed creates the Sales Order'+(engine.normalisePolicy(qt).createProjectOnAcceptance?' and Project':'')+', preserves SKU traceability and prepares purchasing according to the settings saved in this version.':'On acceptance Pool Shed creates the full Project and Sales Order handover using this frozen version.')+'</div><div style="height:10px"></div>'+(check.errors.length?'<div class="qs-notice bad"><b>Fix before publishing</b><br>'+check.errors.map(esc).join('<br>')+'</div>':'')+(check.approval.required?'<div class="qs-notice warn"><b>Commercial approval required</b><br>Resolve the internal exception before publishing.</div>':'')+'<form id="qsPublishForm" class="qs-fields" style="margin-top:12px">'+field('Recipient name','recipientName',c.name||c.companyName||'')+field('Recipient email','recipientEmail',c.email||'','email')+field('Expiry days','expiryDays',30,'number','min="1"')+selectField('Client permissions','permissions','standard',[{value:'standard',label:'Questions + choices + documents + accept'},{value:'view',label:'View + accept only'}])+'<div class="qs-field full"><div class="qs-notice">The customer receives only the private presentation payload. Internal workflow settings, margin, costs, Product Hub supplier data, POs, stock and handover details are never included.</div></div></form></div><footer class="qs-modal-foot">'+button('Preview customer view','preview')+button(check.ok&&!check.approval.required?'Publish secure link':'Publishing blocked','do-publish','primary',check.ok&&!check.approval.required?'':'disabled')+'</footer></div></div>'}
function renderNow(){try{if(typeof render==='function')render();else global.render?.()}catch(e){console.error(e)}}
function render(){if(global.__POOL_SHED_QUOTE_FOCUS__){selectedId=global.__POOL_SHED_QUOTE_FOCUS__;global.__POOL_SHED_QUOTE_FOCUS__='';detailTab='Engagement';const focused=q();selectedSectionId=focused?.sections?.[0]?.id||'';selectedOptionId=focused?.sections?.[0]?.options?.[0]?.id||'';}updateTitle();const target=document.getElementById('screen-quotes');if(!target)return;const sub=activeSub();if(createMode){target.innerHTML=createView();return}if(selectedId){const qt=q();if(!qt){selectedId='';target.innerHTML=listView();return}target.innerHTML=detailView(qt);return}if(sub==='Templates')target.innerHTML=templatesView();else if(sub==='Engagement')target.innerHTML=globalEngagementView();else if(sub==='Approvals')target.innerHTML=approvalsView();else if(sub==='Settings')target.innerHTML=settingsView();else target.innerHTML=listView()}
global.renderQuoteStudioWorkspace=render;
global.PoolShedQuoteStudioWorkspace={
  newQuoteForCustomer:function(customerId){createCustomerId=String(customerId||'');selectedId='';createMode=true;sendModal=false;renderNow();},
  openQuotes:function(){createCustomerId='';selectedId='';createMode=false;sendModal=false;renderNow();}
};
function setQuote(id){selectedId=id;detailTab='Proposal';const qt=q();selectedSectionId=qt?.sections?.[0]?.id||'';selectedOptionId=qt?.sections?.[0]?.options?.[0]?.id||'';selectedBlockId='';builderPanel='sections';createMode=false;sendModal=false;renderNow();if(qt&&engine.refreshMedia)engine.refreshMedia(id).then(r=>{if(r?.updated)renderNow()}).catch(()=>{})}
function preview(qt){if(!qt)return;engine.savePreview(qt);window.open('/proposal?preview=1','_blank','noopener')}
async function doPublish(form){const qt=q();try{const values=Object.fromEntries(new FormData(form));const result=await engine.publish(qt.id,values);sendModal=false;renderNow();if(result.publication.offlinePreview){notify('Secure backend unavailable/offline. Preview created but nothing was sent.');preview(qt);return}notify('Secure proposal V'+result.version.number+' published. Client link is ready.');if(result.publication.clientUrl){try{await navigator.clipboard.writeText(result.publication.clientUrl);notify('Secure client link copied to clipboard.')}catch(_){}window.open(result.publication.clientUrl,'_blank','noopener')}}catch(e){notify(e.message)}}
function changeSelectedOption(section,optionId){if(!section)return;const option=section.options.find(o=>o.id===optionId);if(!option)return;if(section.rule==='locked')return;if(section.rule==='single'||section.rule==='optional')section.options.forEach(o=>o.selected=o.id===optionId);else option.selected=!option.selected;engine.audit(q(),'customer_configuration_edited',{sectionId:section.id,optionId});engine.touch(q());renderNow()}
function addLayout(type){const qt=q();if(!qt)return;const count=(qt.poolLayout.components||[]).length;qt.poolLayout.components.push({id:'LC-'+Date.now().toString(36),type,x:250+(count%4)*95,y:150+Math.floor(count/4)*80,rotation:0});engine.audit(qt,'layout_component_added',{type});engine.touch(qt);renderNow()}
async function quoteImageData(file){if(!file)throw Error('Choose an image first.');if(!/^image\/(jpeg|png|webp)$/i.test(file.type))throw Error('Use a JPG, PNG or WebP image.');if(file.size>12*1024*1024)throw Error('Image is too large. Please use an image under 12 MB.');const bitmap=await new Promise((resolve,reject)=>{const img=new Image(),u=URL.createObjectURL(file);img.onload=()=>{URL.revokeObjectURL(u);resolve(img)};img.onerror=()=>{URL.revokeObjectURL(u);reject(Error('This image could not be opened.'))};img.src=u});let maxW=2000,maxH=1400,scale=Math.min(1,maxW/bitmap.naturalWidth,maxH/bitmap.naturalHeight),w=Math.max(1,Math.round(bitmap.naturalWidth*scale)),h=Math.max(1,Math.round(bitmap.naturalHeight*scale));const canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;const ctx=canvas.getContext('2d',{alpha:false});ctx.fillStyle='#fff';ctx.fillRect(0,0,w,h);ctx.drawImage(bitmap,0,0,w,h);let quality=.86,url=canvas.toDataURL('image/jpeg',quality);while(url.length>900000&&quality>.5){quality-=.07;url=canvas.toDataURL('image/jpeg',quality)}const blob=await (await fetch(url)).blob();if(blob.size>4*1024*1024)throw Error('This image could not be reduced enough. Try a smaller image.');return {url,blob,size:blob.size,width:w,height:h,mime:'image/jpeg'}}
function mediaById(id){return mediaList(q()).find(m=>m.id===id)||null}
function currentMediaTarget(){if(selectedBlockId){const b=selectedBlock();if(b?.type==='gallery')return 'gallery';if(b?.type==='image')return 'block'}if(selectedOptionId)return 'option';return 'library'}
function applyMedia(url,target=mediaTarget){const qt=q();if(!qt)return;if(target==='hero'){qt.presentation.heroImage=url;engine.audit(qt,'hero_image_updated',{});engine.touch(qt);detailTab='Proposal';return}if(target==='option'){const o=selectedOption();if(!o)throw Error('Select an option first.');o.image=url;engine.audit(qt,'option_image_updated',{optionId:o.id});engine.touch(qt);return}const b=selectedBlock();if(target==='block'){if(!b)throw Error('Select an image block first.');b.url=url;engine.audit(qt,'proposal_image_updated',{blockId:b.id});engine.touch(qt);return}if(target==='gallery'){if(!b)throw Error('Select a gallery block first.');b.images=Array.isArray(b.images)?b.images:[];if(b.images.length>=6)throw Error('A gallery can contain up to 6 images.');b.images.push(url);engine.audit(qt,'proposal_gallery_image_added',{blockId:b.id});engine.touch(qt);return}if(target==='library'){const s=selectedSection();if(!s)throw Error('Choose a quote section first.');const nb=engine.addBlock(qt.id,s.id,'image');nb.url=url;selectedBlockId=nb.id;selectedOptionId='';engine.audit(qt,'proposal_image_inserted_from_library',{blockId:nb.id});engine.touch(qt);return}}
async function handleQuoteImage(file,target){const qt=q();if(!qt)return;const media=await quoteImageData(file),token=global.__POOL_SHED_AUTH_TOKEN__?await global.__POOL_SHED_AUTH_TOKEN__():'';let item;if(token&&navigator.onLine){const r=await fetch('/api/quote?action=media-upload&workspace='+encodeURIComponent(global.__POOL_SHED_WORKSPACE_ID__?global.__POOL_SHED_WORKSPACE_ID__():'pool-bros-main')+'&quoteId='+encodeURIComponent(qt.id),{method:'POST',headers:{Authorization:'Bearer '+token,'Content-Type':media.mime,'X-File-Name':encodeURIComponent(file.name||'quote-image.jpg')},body:media.blob}),body=await r.json().catch(()=>({}));if(!r.ok)throw Error(body.error||'Image upload failed');item=engine.addMedia(qt.id,{id:body.media.id,name:body.media.name,type:body.media.type,url:body.media.ref,previewUrl:body.media.previewUrl,storagePath:body.media.storagePath,size:body.media.size})}else{const projected=mediaSize(qt)+media.size;if(projected>1250*1024)throw Error('Offline preview image allowance reached. Connect to upload more images.');item=engine.addMedia(qt.id,{name:file.name,type:'image/jpeg',url:media.url,size:media.size});notify('Offline preview image added. It must be uploaded securely before production publishing.')}applyMedia(item.url,target);notify('Image added to the quote.');renderNow()}
function moveBlock(dir){const s=selectedSection(),i=(s?.blocks||[]).findIndex(b=>b.id===selectedBlockId),j=i+dir;if(!s||i<0||j<0||j>=s.blocks.length)return;[s.blocks[i],s.blocks[j]]=[s.blocks[j],s.blocks[i]];engine.audit(q(),'proposal_block_moved',{blockId:selectedBlockId,direction:dir});engine.touch(q());renderNow()}
function addSectionTemplate(kind){const presets={single:{title:'Choose your preferred option',eyebrow:'Your choices',rule:'single',required:true,layout:'cards'},optional:{title:'Optional enhancements',eyebrow:'Enhance your project',rule:'multi',required:false,priceMode:'upgrade',layout:'cards'},locked:{title:'Included specification',eyebrow:'Included in your proposal',rule:'locked',required:false,priceMode:'included',layout:'rows'}};const s=engine.addSection(selectedId,presets[kind]||{});selectedSectionId=s.id;selectedOptionId='';selectedBlockId='';builderPanel='sections';renderNow()}
function nextNavigation(tab){if(global.__POOL_SHED_OPEN_TAB__)global.__POOL_SHED_OPEN_TAB__(tab)}
document.addEventListener('click',async function(e){const action=e.target.closest('[data-qs-action]');const open=e.target.closest('[data-qs-open]');if(open){setQuote(open.dataset.qsOpen);return}const openBtn=e.target.closest('[data-quote-id]');if(openBtn&&openBtn.dataset.qsAction==='open-quote'){setQuote(openBtn.dataset.quoteId);return}const tab=e.target.closest('[data-qs-tab]');if(tab){detailTab=tab.dataset.qsTab;selectedBlockId='';renderNow();return}const builder=e.target.closest('[data-qs-builder-panel]');if(builder){builderPanel=builder.dataset.qsBuilderPanel;renderNow();return}const builderElements=e.target.closest('[data-qs-action=builder-elements]');if(builderElements){builderPanel='elements';renderNow();return}const section=e.target.closest('[data-qs-section]');if(section){selectedSectionId=section.dataset.qsSection;selectedOptionId='';selectedBlockId='';renderNow();return}const blockSelect=e.target.closest('[data-qs-block]');if(blockSelect){selectedBlockId=blockSelect.dataset.qsBlock;selectedOptionId='';renderNow();return}const optionCard=e.target.closest('[data-qs-option-card]');if(optionCard&&!e.target.closest('[data-qs-select-option]')){selectedOptionId=optionCard.dataset.qsOptionCard;selectedBlockId='';renderNow();return}const option=e.target.closest('[data-qs-option]');if(option){selectedOptionId=option.dataset.qsOption;selectedBlockId='';renderNow();return}const sectionTemplate=e.target.closest('[data-qs-section-template]');if(sectionTemplate){addSectionTemplate(sectionTemplate.dataset.qsSectionTemplate);return}const choose=e.target.closest('[data-qs-select-option]');if(choose){changeSelectedOption(selectedSection(),choose.dataset.qsSelectOption);return}const addProduct=e.target.closest('[data-qs-add-product]');if(addProduct){try{const o=engine.addProductOption(selectedId,selectedSectionId,addProduct.dataset.qsAddProduct);selectedOptionId=o.id;selectedBlockId='';builderPanel='products';notify('Product added to quote section.');renderNow()}catch(err){notify(err.message)}return}const upload=e.target.closest('[data-qs-upload-target]');if(upload){mediaTarget=upload.dataset.qsUploadTarget||currentMediaTarget();const input=document.getElementById('qsImageUpload')||document.createElement('input');if(!input.id){input.id='qsImageUpload';input.type='file';input.accept='image/jpeg,image/png,image/webp';input.hidden=true;document.body.appendChild(input)}input.value='';input.click();return}const useMedia=e.target.closest('[data-qs-use-media]');if(useMedia){const m=mediaById(useMedia.dataset.qsUseMedia);if(m){try{applyMedia(m.url,currentMediaTarget());notify('Image applied.');renderNow()}catch(err){notify(err.message)}}return}const removeMedia=e.target.closest('[data-qs-remove-media]');if(removeMedia){engine.removeMedia(selectedId,removeMedia.dataset.qsRemoveMedia);notify('Image removed from this quote library.');renderNow();return}const block=e.target.closest('[data-qs-add-block]');if(block){try{const b=engine.addBlock(selectedId,selectedSectionId,block.dataset.qsAddBlock);selectedBlockId=b.id;selectedOptionId='';builderPanel='elements';renderNow()}catch(err){notify(err.message)}return}const shape=e.target.closest('[data-qs-shape]');if(shape){q().poolLayout.shape=shape.dataset.qsShape;engine.audit(q(),'pool_shape_changed',{shape:shape.dataset.qsShape});engine.touch(q());renderNow();return}const comp=e.target.closest('[data-qs-component]');if(comp){addLayout(comp.dataset.qsComponent);return}const item=e.target.closest('[data-qs-layout-item]');if(item){layoutSelected=item.dataset.qsLayoutItem;renderNow();return}const itemSelect=e.target.closest('[data-qs-layout-select]');if(itemSelect){layoutSelected=itemSelect.dataset.qsLayoutSelect;renderNow();return}if(!action)return;const a=action.dataset.qsAction;
 if(a==='new-quote'){createCustomerId='';createMode=true;selectedId='';renderNow()}else if(a==='cancel-create'){createCustomerId='';createMode=false;renderNow()}else if(a==='back-list'){selectedId='';createMode=false;sendModal=false;renderNow()}else if(a==='open-quote'){setQuote(action.dataset.quoteId)}else if(a==='refresh'){renderNow()}else if(a==='templates'){selectedId='';createMode=false;try{activeSubPage.quotes='Templates'}catch(_){}renderNow()}else if(a==='preview'){preview(q())}else if(a==='publish'){sendModal=true;renderNow()}else if(a==='close-send'){sendModal=false;renderNow()}else if(a==='do-publish'){const form=document.getElementById('qsPublishForm');if(form)await doPublish(form)}else if(a==='add-section'){const s=engine.addSection(selectedId,{title:'New choice section'});selectedSectionId=s.id;selectedOptionId='';selectedBlockId='';renderNow()}else if(a==='duplicate-section'){const s=engine.duplicateSection(selectedId,selectedSectionId);selectedSectionId=s.id;selectedOptionId=s.options?.[0]?.id||'';selectedBlockId='';renderNow()}else if(a==='delete-section'){try{engine.deleteSection(selectedId,selectedSectionId);selectedSectionId=q().sections[0]?.id||'';selectedOptionId='';renderNow()}catch(err){notify(err.message)}}else if(a==='add-custom'){const o=engine.addCustomOption(selectedId,selectedSectionId,{title:'Bespoke project option'});selectedOptionId=o.id;selectedBlockId='';renderNow()}else if(a==='clear-block-selection'){selectedBlockId='';renderNow()}else if(a==='move-block-up'){moveBlock(-1)}else if(a==='move-block-down'){moveBlock(1)}else if(a==='duplicate-block'){const s=selectedSection(),b=selectedBlock();if(s&&b){const cp=JSON.parse(JSON.stringify(b));cp.id='BLK-'+Date.now().toString(36).toUpperCase();const i=s.blocks.findIndex(x=>x.id===b.id);s.blocks.splice(i+1,0,cp);selectedBlockId=cp.id;engine.touch(q());renderNow()}}else if(a==='remove-block'){const s=selectedSection();if(s&&selectedBlockId){s.blocks=s.blocks.filter(b=>b.id!==selectedBlockId);selectedBlockId='';engine.touch(q());renderNow()}}else if(a==='remove-option-image'){const o=selectedOption();if(o){o.image='';engine.touch(q());renderNow()}}else if(a==='remove-hero-image'){q().presentation.heroImage='';engine.touch(q());renderNow()}else if(a==='remove-option'){const s=selectedSection();if(s&&selectedOptionId){s.options=s.options.filter(o=>o.id!==selectedOptionId);selectedOptionId=s.options[0]?.id||'';engine.audit(q(),'quote_option_removed',{});engine.touch(q());renderNow()}}else if(a==='clear-layout'){q().poolLayout.components=[];layoutSelected='';engine.touch(q());renderNow()}else if(a==='remove-layout-item'){if(layoutSelected){q().poolLayout.components=q().poolLayout.components.filter(x=>x.id!==layoutSelected);layoutSelected='';engine.touch(q());renderNow()}}else if(a==='approve-exception'){engine.recordApproval(selectedId,'Commercial exception','Approved','Approved in Quote Studio');renderNow()}else if(a==='create-revision'){const r=engine.createRevision(selectedId);setQuote(r.id);notify('New draft revision created.')}else if(a==='convert-accepted'){try{engine.convertAccepted(selectedId,q().publishedVersion,{source:'Staff conversion'});renderNow()}catch(err){notify(err.message)}}else if(a==='queue-deposit'){try{await engine.queueDeposit(selectedId);notify('Payment request queued to Xero.');renderNow()}catch(err){notify(err.message)}}else if(a==='mark-paid'){try{engine.markDepositPaid(selectedId);notify('Payment recorded. Procurement gate cleared.');renderNow()}catch(err){notify(err.message)}}else if(a==='release-pos'){try{engine.releasePurchaseOrders(selectedId);notify('Purchase orders moved to Ready to Order.');renderNow()}catch(err){notify(err.message)}}else if(a==='open-project'){nextNavigation('jobs')}else if(a==='open-so'){nextNavigation('salesorders')}else if(a==='open-purchase'){nextNavigation('purchase')}
});
document.addEventListener('input',e=>{if(e.target.matches('[data-qs-list-search]')){listSearch=e.target.value;renderNow()}if(e.target.matches('[data-qs-product-search]')){productSearch=e.target.value;renderNow()}});
document.addEventListener('change',async e=>{if(e.target.id==='qsImageUpload'&&e.target.files?.[0]){try{await handleQuoteImage(e.target.files[0],mediaTarget)}catch(err){notify(err.message)}return}if(e.target.matches('[data-qs-page-visible]')){const p=q()?.pages?.find(x=>x.id===e.target.dataset.qsPageVisible);if(p){p.visible=e.target.checked;engine.touch(q())}}if(e.target.matches('[name=qsWorkflowPreview]')){document.querySelectorAll('.qs-workflow-card').forEach(x=>x.classList.toggle('active',x.contains(e.target)&&e.target.checked));const form=document.getElementById('qsCreateForm');if(!form)return;const mode=e.target.value,workflow=form.elements.workflow,project=form.elements.createProjectOnAcceptance,xero=form.elements.xeroRequestMode,gate=form.elements.requirePaymentBeforePORelease,btn=form.querySelector('button[type=submit]'),hint=document.getElementById('qsWorkflowHint');workflow.value=mode;if(mode==='quick'){project.value='no';xero.value='full';gate.value='yes';if(btn)btn.textContent='Create Quick Quote';if(hint)hint.textContent='Quick Quote will create a Sales Order automatically when accepted. A Project will not be created unless you choose it above.'}else{project.value='yes';xero.value='deposit';gate.value='yes';if(btn)btn.textContent='Create Project Proposal';if(hint)hint.textContent='Project Proposal will create the full Project and linked Sales Order when accepted.'}}});
document.addEventListener('paste',async e=>{if(!selectedId)return;if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;const item=[...(e.clipboardData?.items||[])].find(x=>String(x.type||'').startsWith('image/'));if(!item)return;const f=item.getAsFile();if(!f)return;e.preventDefault();try{await handleQuoteImage(f,currentMediaTarget());notify('Pasted image added to the quote.')}catch(err){notify(err.message)}});
document.addEventListener('dragover',e=>{const z=e.target.closest('.qs-upload-zone');if(z){e.preventDefault();z.classList.add('dragging')}});document.addEventListener('dragleave',e=>{const z=e.target.closest('.qs-upload-zone');if(z)z.classList.remove('dragging')});document.addEventListener('drop',async e=>{const z=e.target.closest('.qs-upload-zone');if(!z)return;e.preventDefault();z.classList.remove('dragging');const f=e.dataTransfer?.files?.[0];if(!f)return;try{mediaTarget=z.dataset.qsUploadTarget||'library';await handleQuoteImage(f,mediaTarget)}catch(err){notify(err.message)}});
document.addEventListener('submit',e=>{if(!e.target.id?.startsWith('qs'))return;e.preventDefault();const v=Object.fromEntries(new FormData(e.target));try{
 if(e.target.id==='qsCreateForm'){const qt=engine.createQuote(v);createCustomerId='';createMode=false;setQuote(qt.id);notify(qt.id+' created.');return}
 if(e.target.id==='qsWorkflowForm'){const qt=q();if(['Accepted','Won'].includes(qt.status))throw Error('Accepted workflow is locked. Create a revision.');qt.workflow=v.workflow==='quick'?'quick':'project';const hp=engine.normalisePolicy(qt);hp.createProjectOnAcceptance=v.createProjectOnAcceptance==='yes';hp.allocateStockOnAcceptance=v.allocateStockOnAcceptance==='yes';hp.createDraftPurchaseOrders=v.createDraftPurchaseOrders==='yes';hp.xeroRequestMode=v.xeroRequestMode;hp.requirePaymentBeforePORelease=v.requirePaymentBeforePORelease==='yes';engine.audit(qt,'workflow_updated',{workflow:qt.workflow,handoverPolicy:hp});engine.touch(qt);notify('Quote workflow saved.');detailTab='Proposal';renderNow();return}
 if(e.target.id==='qsProposalForm'){const qt=q();if(['Accepted','Won'].includes(qt.status))throw Error('Accepted quote is locked. Create a revision.');qt.projectName=v.projectName;qt.projectType=v.projectType;qt.validUntil=v.validUntil;qt.termsVersion=v.termsVersion;qt.presentation.heroTitle=v.heroTitle;qt.presentation.heroIntro=v.heroIntro;qt.presentation.heroImagePosition=['left','center','right'].includes(v.heroImagePosition)?v.heroImagePosition:'center';qt.presentation.about=v.about;engine.audit(qt,'presentation_updated',{});engine.touch(qt);notify('Presentation saved.');renderNow();return}
 if(e.target.id==='qsSectionForm'){const s=selectedSection();Object.assign(s,{title:v.title,eyebrow:v.eyebrow,intro:v.intro,rule:v.rule,layout:v.layout||s.layout,priceMode:v.priceMode,questions:e.target.elements.questions?.checked!==false,showSummary:e.target.elements.showSummary?.checked!==false});s.style=s.style||{};s.style.columns=Number(v.columns||s.style.columns||3);engine.audit(q(),'section_updated',{sectionId:s.id});engine.touch(q());notify('Section saved.');renderNow();return}
 if(e.target.id==='qsOptionForm'){const o=selectedOption();Object.assign(o,{title:v.title,subtitle:v.subtitle,description:v.description,qty:Number(v.qty||1),unitPrice:Number(v.unitPrice||0),badge:v.badge||'',benefits:String(v.benefits||'').split(',').map(x=>x.trim()).filter(Boolean),selected:e.target.elements.selected.checked,recommended:e.target.elements.recommended.checked,visible:e.target.elements.visible.checked});if(selectedSection().rule==='single'&&o.selected)selectedSection().options.forEach(x=>{if(x.id!==o.id)x.selected=false});engine.audit(q(),'option_updated',{optionId:o.id});engine.touch(q());notify('Option saved.');renderNow();return}
 if(e.target.id==='qsBlockForm'){const b=selectedBlock();if(!b)throw Error('Select a proposal layer.');if(v.title!=null)b.title=v.title;if(v.text!=null)b.text=v.text;b.style=b.style||{};b.style.align=v.align||b.style.align||'left';if(v.size!=null)b.style.size=Number(v.size||b.style.size||16);engine.audit(q(),'proposal_block_updated',{blockId:b.id});engine.touch(q());notify('Proposal layer saved.');renderNow();return}
 if(e.target.id==='qsLayoutForm'){const l=q().poolLayout;['length','width','shallowDepth','deepDepth','shallowLength','slopeLength'].forEach(k=>{if(v[k]!=null)l[k]=Number(v[k])});l.notes=v.notes||'';engine.audit(q(),'pool_layout_updated',{});engine.touch(q());notify('Pool layout saved.');renderNow();return}
 if(e.target.id==='qsSettingsForm'){const s=engine.settings();Object.assign(s,{brandName:v.brandName,brandDescriptor:v.brandDescriptor,termsVersion:v.termsVersion,validDays:Number(v.validDays||30),depositPercent:Number(v.depositPercent||50),minimumMargin:Number(v.minimumMargin||25),primary:v.primary,accent:v.accent});save();notify('Quote Studio defaults saved.');renderNow();return}
 }catch(err){notify(err.message)}});

let qsRemoteSyncBusy=false;
